async function main() {
  const category = await prisma.category.upsert({
    where: { slug: categoryData.slug },
    update: { name: categoryData.name },
    create: {
      group: "Technology", name: categoryData.name, slug: categoryData.slug },
  });

  const subcategoryMap = new Map<string, string>();
  for (const subcategory of subcategories) {
    const record = await prisma.subcategory.upsert({
      where: { categoryId_slug: { categoryId: category.id, slug: subcategory.slug } },
      update: { name: subcategory.name, categoryId: category.id },
      create: { name: subcategory.name, slug: subcategory.slug, categoryId: category.id },
    });
    subcategoryMap.set(subcategory.slug, record.id);
  }

  for (const item of questions) {
    const subcategoryId = subcategoryMap.get(item.subcategorySlug);
    if (!subcategoryId) throw new Error(`Missing subcategory: ${item.subcategorySlug}`);

    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: item.experienceLevel,
        difficulty: item.difficulty,
        interviewType: item.interviewType,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: item.experienceLevel,
        difficulty: item.difficulty,
        interviewType: item.interviewType,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
    });
  }

  console.log(`Data Science interview seed completed: ${questions.length} questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });